import{_ as r,r as t,o as i,c as l,e,a as n,s as o,d as a}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Data Sources - October CMS - 4.x","titleTemplate":false,"description":"Provides an interface for accessing generic data.","frontmatter":{"subtitle":"Provides an interface for accessing generic data."},"headers":[{"level":2,"title":"Creating Data Sources","slug":"creating-data-sources","link":"#creating-data-sources","children":[{"level":3,"title":"Registering Dimensions","slug":"registering-dimensions","link":"#registering-dimensions","children":[]},{"level":3,"title":"Registering Metrics","slug":"registering-metrics","link":"#registering-metrics","children":[]},{"level":3,"title":"Returning Data from a Data Source","slug":"returning-data-from-a-data-source","link":"#returning-data-from-a-data-source","children":[{"level":4,"title":"Using ReportQueryBuilder (Recommended)","slug":"using-reportquerybuilder-recommended","link":"#using-reportquerybuilder-recommended","children":[]},{"level":4,"title":"Building Queries Manually","slug":"building-queries-manually","link":"#building-queries-manually","children":[]},{"level":4,"title":"Semantic Group Interval Methods","slug":"semantic-group-interval-methods","link":"#semantic-group-interval-methods","children":[]},{"level":4,"title":"Conditional Configuration","slug":"conditional-configuration","link":"#conditional-configuration","children":[]},{"level":4,"title":"Available ReportQueryBuilder Methods","slug":"available-reportquerybuilder-methods","link":"#available-reportquerybuilder-methods","children":[]},{"level":4,"title":"Pre-Aggregated Data","slug":"pre-aggregated-data","link":"#pre-aggregated-data","children":[]}]},{"level":3,"title":"Formatting Metrics Data","slug":"formatting-metrics-data","link":"#formatting-metrics-data","children":[]},{"level":3,"title":"Custom Display Formatting","slug":"custom-display-formatting","link":"#custom-display-formatting","children":[]},{"level":3,"title":"Displaying Extra Dimension Data","slug":"displaying-extra-dimension-data","link":"#displaying-extra-dimension-data","children":[]},{"level":3,"title":"Using the Data Source","slug":"using-the-data-source","link":"#using-the-data-source","children":[]},{"level":3,"title":"Legacy ReportDataQueryBuilder","slug":"legacy-reportdataquerybuilder","link":"#legacy-reportdataquerybuilder","children":[]}]}],"relativePath":"4.x/extend/dashboards/data-sources.md","filePath":"4.x/extend/dashboards/data-sources.md"}'),u={name:"4.x/extend/dashboards/data-sources.md"};function d(k,s,g,m,h,f){const p=t("pre-heading"),c=t("post-heading");return i(),l("div",null,[e(p),s[0]||(s[0]=n("h1",null,"Data Sources",-1)),e(c),s[1]||(s[1]=o(`<h2 id="creating-data-sources"><a href="#creating-data-sources" class="header-anchor">#</a> Creating Data Sources</h2><p>Every plugin can register any number of data sources. It is recommended to create a new data source for each type of data provided by a plugin. For example, if a plugin offers both customer and sales data, having two separate data sources would simplify widget configuration for end users.</p><p>Data sources are classes that extend the <code>Dashboard\\Classes\\ReportDataSourceBase</code> class. Each data source must register at least one metric and one dimension. In addition, data source classes must implement the <code>fetchData</code> method, which is required to return the <code>ReportFetchDataResult</code> object. In most cases, when your data source fetches data from the database, you can use the <code>ReportQueryBuilder</code> class, which provides a fluent interface for constructing and executing database queries based on the dimension and metrics configuration.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Db</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Carbon<span class="token punctuation">\\</span>Carbon</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportMetric</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportDimension</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportDimensionField</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportDataSourceBase</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportFetchData</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportFetchDataResult</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportQueryBuilder</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyReportDataSource</span> <span class="token keyword">extends</span> <span class="token class-name">ReportDataSourceBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// Register dimensions and metrics here</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">protected</span> <span class="token keyword">function</span> <span class="token function-definition function">fetchData</span><span class="token punctuation">(</span><span class="token class-name type-declaration">ReportFetchData</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token class-name return-type">ReportFetchDataResult</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// Construct and return a ReportFetchDataResult object,</span>
        <span class="token comment">// or use the ReportQueryBuilder class to do the hard work.</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>ReportFetchData</code> object has the following properties available.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>$dimension</strong></td><td><code>ReportDimension</code></td><td>the dimension to group the data by</td></tr><tr><td><strong>$dimensionCode</strong></td><td><code>string</code></td><td>the dimension code string</td></tr><tr><td><strong>$metrics</strong></td><td><code>array</code></td><td>the metrics to return (array of <code>ReportMetric</code> objects)</td></tr><tr><td><strong>$metricCodes</strong></td><td><code>array</code></td><td>the metric code strings</td></tr><tr><td><strong>$metricsConfiguration</strong></td><td><code>array</code></td><td>the report metrics configuration (array of <code>ReportMetricConfiguration</code> objects)</td></tr><tr><td><strong>$dateStart</strong></td><td><code>?Carbon</code></td><td>the start date</td></tr><tr><td><strong>$dateEnd</strong></td><td><code>?Carbon</code></td><td>the end date</td></tr><tr><td><strong>$compareDateStart</strong></td><td><code>?Carbon</code></td><td>the comparison period start date (for period-over-period comparisons)</td></tr><tr><td><strong>$compareDateEnd</strong></td><td><code>?Carbon</code></td><td>the comparison period end date</td></tr><tr><td><strong>$startTimestamp</strong></td><td><code>?int</code></td><td>optional starting timestamp for relative intervals (e.g., past hour)</td></tr><tr><td><strong>$dimensionFilters</strong></td><td><code>array</code></td><td>the filters to apply to the dimension values (array of <code>ReportDimensionFilter</code> objects)</td></tr><tr><td><strong>$groupInterval</strong></td><td><code>?string</code></td><td>the group interval (one of the <code>GROUP_INTERVAL_*</code> constants: DAY, WEEK, MONTH, QUARTER, YEAR, FULL)</td></tr><tr><td><strong>$orderRule</strong></td><td><code>?ReportDataOrderRule</code></td><td>the data ordering rule</td></tr><tr><td><strong>$limit</strong></td><td><code>?int</code></td><td>the maximum number of records to return</td></tr><tr><td><strong>$paginationParams</strong></td><td><code>?ReportDataPaginationParams</code></td><td>the pagination parameters</td></tr><tr><td><strong>$hideEmptyDimensionValues</strong></td><td><code>bool</code></td><td>indicates whether empty dimension values must be removed from the dataset</td></tr><tr><td><strong>$totalsOnly</strong></td><td><code>bool</code></td><td>indicates that the method should only return total values for metrics, and not rows</td></tr><tr><td><strong>$resetCache</strong></td><td><code>bool</code></td><td>indicates that the cache should be reset</td></tr></tbody></table></div><p>Plugins must register their data sources in the Plugin Registration file (Plugin.php), within the <code>boot</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>DashManager</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">DashManager</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">registerDataSourceClass</span><span class="token punctuation">(</span>
        <span class="token class-name static-context">MyReportDataSource</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;My Custom Data Source&#39;</span> <span class="token comment">// This can be a reference to a localization string</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>We will use a simple ecommerce plugin database structure for the documentation examples. The plugin includes the following tables.</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/data-source-data-structure.png" alt="image"></p><p>We&#39;ll create a data source to display sales data for products and categories in the form of a table, graph, and indicator.</p><h3 id="registering-dimensions"><a href="#registering-dimensions" class="header-anchor">#</a> Registering Dimensions</h3><p>Data sources must register their metrics and dimensions in the constructor. Use the <code>registerDimension</code> method to register a dimension. Let&#39;s begin by registering the product dimension for our e-commerce plugin example.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">DIMENSION_PRODUCT</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;product&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerDimension</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportDimension</span><span class="token punctuation">(</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">DIMENSION_PRODUCT</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;acme_shop_products.id&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;Product&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;product_name&#39;</span>
    <span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>registerDimension</code> method accepts a <code>ReportDimension</code> object. The constructor for <code>ReportDimension</code> takes the following arguments.</p><div class="table"><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>$code</strong></td><td><code>string</code></td><td>specifies the dimension referral code. Your data source will use this code to distinguish the dimension in the <code>fetchData</code> calls. It can be a simple string, for example, “city”.</td></tr><tr><td><strong>$databaseColumnName</strong></td><td><code>string</code></td><td>specifies the dimension column name in the data source table. The column name is used in <code>ReportDataQueryBuilder</code> to construct database queries. Including the table name (<code>acme_shop_products</code> in this case) along with the column name is often necessary to avoid ambiguity when the data source query includes multiple tables. If your data source is not database-driven, any value can be used for this argument. In most instances, the dimension column corresponds to the primary key in the dimension table.</td></tr><tr><td><strong>$displayName</strong></td><td><code>string</code></td><td>specifies the dimension name used in reports. For example, in the Table widget, this could become the title of the dimension column. It is also used in the widget configuration popup, in the dimension dropdown. The value for this argument can be a static string, or a reference to a localization string.</td></tr><tr><td><strong>$labelColumnName</strong></td><td><code>?string</code></td><td>specifies the name of the column for the dimension label. Use this column to provide a user-friendly label for the dimension. If this argument is not provided, the value of <code>$databaseColumnName</code> is used as the dimension label. Keep in mind that widget dimension sorting and filters will utilize the dimension label value when the label column name provided.</td></tr></tbody></table></div><p>The <code>registerDimension</code> method returns the registered dimension object, allowing for chaining.</p><p>After registering the data source and dimension, you should be able to view them in the dashboard widget configurator.</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/dimension-dropdown.png" alt="image"></p><h3 id="registering-metrics"><a href="#registering-metrics" class="header-anchor">#</a> Registering Metrics</h3><p>We can register two metrics associated with products: sale amount and quantity. These metrics are registered using the <code>registerMetric</code> method of the data source class.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">METRIC_TOTAL_AMOUNT</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;total_amount&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token constant">METRIC_TOTAL_QUANTITY</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;total_quantity&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token operator">...</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerMetric</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportMetric</span><span class="token punctuation">(</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">METRIC_TOTAL_AMOUNT</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;acme_shop_sales.total&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;Total amount&#39;</span><span class="token punctuation">,</span>
        <span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_SUM</span>
    <span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerMetric</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportMetric</span><span class="token punctuation">(</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">METRIC_TOTAL_QUANTITY</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;acme_shop_sales.quantity&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;Quantity&#39;</span><span class="token punctuation">,</span>
        <span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_SUM</span>
    <span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>registerMetric</code> method accepts a <code>ReportMetric</code> object. The constructor for this class has the following arguments:</p><div class="table"><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>$code</strong></td><td><code>string</code></td><td>the metric referral code.</td></tr><tr><td><strong>$databaseColumnName</strong></td><td><code>string</code></td><td>the metric column name. It&#39;s always a good idea to provide the table name along with the field name to avoid ambiguity in SQL queries.</td></tr><tr><td><strong>$displayName</strong></td><td><code>string</code></td><td>the metric name used in reports.</td></tr><tr><td><strong>$aggregateFunction</strong></td><td><code>string</code></td><td>the aggregate function for the metric. One of the <code>ReportMetric::AGGREGATE_XXX</code> constants.</td></tr><tr><td><strong>$intlFormatOptions</strong></td><td><code>?array</code></td><td>client-side formatting options, compatible with the <code>Intl.NumberFormat()</code> constructor options argument. Skip the argument to use the default formatting options.</td></tr></tbody></table></div><p>The dashboard can aggregate metric data using one of the following functions:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_SUM</span>
<span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_AVG</span>
<span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_MIN</span>
<span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_MAX</span>
<span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_COUNT</span>
<span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_NONE</span>
<span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_COUNT_DISTINCT</span>
<span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_COUNT_DISTINCT_NOT_NULL</span>
</code></pre></div><p>For our needs, the <code>SUM</code> function is the most suitable as our metrics are the total quantity and amount. Therefore, we use <code>ReportMetric::AGGREGATE_SUM</code> in the constructors of both metrics.</p><p>After registering the metrics, you can add them to a dashboard widget configuration:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/metrics.png" alt="image"></p><h3 id="returning-data-from-a-data-source"><a href="#returning-data-from-a-data-source" class="header-anchor">#</a> Returning Data from a Data Source</h3><p>Data sources should implement the <code>fetchData</code> method to return data for the requested dimension, metrics, and dimension fields. The <code>ReportQueryBuilder</code> class provides a fluent interface that makes this straightforward.</p><p>The use of <code>ReportQueryBuilder</code> is optional. The sole requirement for the <code>fetchData</code> method is to return a <code>Dashboard\\Classes\\ReportFetchDataResult</code> object. If your data source doesn&#39;t work with a database, or if you need more control, you can use native Laravel classes to load the data.</p><h4 id="using-reportquerybuilder-recommended"><a href="#using-reportquerybuilder-recommended" class="header-anchor">#</a> Using ReportQueryBuilder (Recommended)</h4><p>The simplest way to implement <code>fetchData</code> is using the <code>fromFetchData</code> static method, which automatically configures the builder from the request data:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token keyword">function</span> <span class="token function-definition function">fetchData</span><span class="token punctuation">(</span><span class="token class-name type-declaration">ReportFetchData</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token class-name return-type">ReportFetchDataResult</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dimension</span><span class="token operator">-&gt;</span><span class="token function">getCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">!==</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">DIMENSION_PRODUCT</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">SystemException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Invalid dimension&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token class-name static-context">ReportQueryBuilder</span><span class="token operator">::</span><span class="token function">fromFetchData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme_shop_products&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">dateColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales.sale_date&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">onConfigureMetrics</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$dimension</span><span class="token punctuation">,</span> <span class="token variable">$metrics</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$join</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token variable">$join</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales.product_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme_shop_products.id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metricsConfiguration</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>fromFetchData</code> method accepts the <code>ReportFetchData</code> object and the main table name. It automatically configures:</p><ul><li>The dimension and metrics from the request</li><li>Ordering, filtering, pagination, and limits</li><li>Date range and group interval settings</li><li>The <code>totalsOnly</code> and <code>hideEmptyValues</code> flags</li></ul><p>You then chain additional configuration:</p><ul><li><code>dateColumn()</code> - specifies the column used to filter by the user&#39;s selected date range</li><li><code>timestampColumn()</code> - optional column for relative time filtering (e.g., &quot;past hour&quot;)</li><li><code>onConfigureMetrics()</code> - callback to join tables or configure metric columns</li><li><code>onConfigureQuery()</code> - callback for additional query customization</li></ul><h4 id="building-queries-manually"><a href="#building-queries-manually" class="header-anchor">#</a> Building Queries Manually</h4><p>For more control, you can build the query step by step using the fluent interface:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token keyword">function</span> <span class="token function-definition function">fetchData</span><span class="token punctuation">(</span><span class="token class-name type-declaration">ReportFetchData</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token class-name return-type">ReportFetchDataResult</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">ReportQueryBuilder</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_products&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">dimension</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dimension</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">metrics</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metrics</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">orderRule</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">filters</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dimensionFilters</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">limit</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">limit</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">groupInterval</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">groupInterval</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">hideEmptyValues</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">hideEmptyDimensionValues</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">dateRange</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dateStart</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dateEnd</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme_shop_sales.sale_date&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">totalsOnly</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">totalsOnly</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">onConfigureMetrics</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$dimension</span><span class="token punctuation">,</span> <span class="token variable">$metrics</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$join</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token variable">$join</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales.product_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme_shop_products.id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metricsConfiguration</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="semantic-group-interval-methods"><a href="#semantic-group-interval-methods" class="header-anchor">#</a> Semantic Group Interval Methods</h4><p>For date-based dimensions, you can use semantic methods instead of passing interval constants:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ReportQueryBuilder</span><span class="token operator">::</span><span class="token function">fromFetchData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">dateColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;order_date&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">groupByYear</span><span class="token punctuation">(</span><span class="token punctuation">)</span>    <span class="token comment">// or groupByMonth(), groupByWeek(), groupByDay(), groupByQuarter()</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metricsConfiguration</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="conditional-configuration"><a href="#conditional-configuration" class="header-anchor">#</a> Conditional Configuration</h4><p>Use the <code>when()</code> method to conditionally apply configuration:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ReportQueryBuilder</span><span class="token operator">::</span><span class="token function">fromFetchData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">dateColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;order_date&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">limit</span><span class="token punctuation">,</span> <span class="token keyword">fn</span><span class="token punctuation">(</span><span class="token variable">$builder</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token variable">$builder</span><span class="token operator">-&gt;</span><span class="token function">limit</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">limit</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token variable">$onlyCompleted</span><span class="token punctuation">,</span> <span class="token keyword">fn</span><span class="token punctuation">(</span><span class="token variable">$builder</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token variable">$builder</span><span class="token operator">-&gt;</span><span class="token function">onConfigureQuery</span><span class="token punctuation">(</span>
        <span class="token keyword">fn</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;completed&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">)</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metricsConfiguration</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="available-reportquerybuilder-methods"><a href="#available-reportquerybuilder-methods" class="header-anchor">#</a> Available ReportQueryBuilder Methods</h4><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>table($name)</code></td><td>Static constructor - creates builder for the given table</td></tr><tr><td><code>fromFetchData($data, $table)</code></td><td>Static constructor - creates builder from ReportFetchData</td></tr><tr><td><code>dimension($dimension)</code></td><td>Sets the dimension to group by</td></tr><tr><td><code>metrics($metrics)</code></td><td>Sets the metrics array</td></tr><tr><td><code>addMetric($metric)</code></td><td>Adds a single metric</td></tr><tr><td><code>orderBy($rule)</code></td><td>Sets the ordering rule</td></tr><tr><td><code>filters($filters)</code></td><td>Sets dimension filters</td></tr><tr><td><code>limit($limit)</code></td><td>Sets maximum number of results</td></tr><tr><td><code>paginate($params)</code></td><td>Sets pagination parameters</td></tr><tr><td><code>groupInterval($interval)</code></td><td>Sets the grouping interval</td></tr><tr><td><code>groupByDay()</code></td><td>Groups by day</td></tr><tr><td><code>groupByWeek()</code></td><td>Groups by week</td></tr><tr><td><code>groupByMonth()</code></td><td>Groups by month</td></tr><tr><td><code>groupByQuarter()</code></td><td>Groups by quarter</td></tr><tr><td><code>groupByYear()</code></td><td>Groups by year</td></tr><tr><td><code>withoutGrouping()</code></td><td>Disables grouping (full interval)</td></tr><tr><td><code>dateRange($start, $end, $column)</code></td><td>Sets date range and optional column</td></tr><tr><td><code>dateColumn($column)</code></td><td>Sets the date column for filtering</td></tr><tr><td><code>sinceTimestamp($ts, $column)</code></td><td>Sets relative timestamp filtering</td></tr><tr><td><code>timestampColumn($column)</code></td><td>Sets the timestamp column</td></tr><tr><td><code>hideEmptyValues($hide)</code></td><td>Hides null dimension values</td></tr><tr><td><code>totalsOnly($totals)</code></td><td>Returns only totals, not rows</td></tr><tr><td><code>onConfigureQuery($callback)</code></td><td>Registers query customization callback</td></tr><tr><td><code>onConfigureMetrics($callback)</code></td><td>Registers metrics configuration callback</td></tr><tr><td><code>onConfigureMetric($callback)</code></td><td>Registers per-metric configuration callback</td></tr><tr><td><code>when($condition, $callback)</code></td><td>Conditionally applies configuration</td></tr><tr><td><code>get($metricsConfig, $urlTemplate)</code></td><td>Executes query and returns results</td></tr><tr><td><code>toSql()</code></td><td>Returns the SQL string (for debugging)</td></tr></tbody></table></div><h4 id="pre-aggregated-data"><a href="#pre-aggregated-data" class="header-anchor">#</a> Pre-Aggregated Data</h4><p>When using <code>ReportQueryBuilder</code> or <code>ReportDataQueryBuilder</code>, data is aggregated at the SQL level using <code>GROUP BY</code> and aggregate functions. The query builders automatically signal this to the framework so that the results are only normalized (gap-filled with missing periods) and not re-aggregated in PHP.</p><p>If your data source performs its own aggregation, for example, fetching pre-grouped data from an external API or using custom SQL — you should set the pre-aggregated flag on the result to prevent double aggregation:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token keyword">function</span> <span class="token function-definition function">fetchData</span><span class="token punctuation">(</span><span class="token class-name type-declaration">ReportFetchData</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token class-name return-type">ReportFetchDataResult</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Data is already aggregated by the group interval</span>
    <span class="token variable">$rows</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fetchFromExternalApi</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$result</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ReportFetchDataResult</span><span class="token punctuation">(</span><span class="token variable">$rows</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$result</span><span class="token operator">-&gt;</span><span class="token function">setPreAggregated</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$result</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>When <code>setPreAggregated</code> is set, the framework will still normalize the data for date dimensions (filling in missing date periods with null values) but will not re-aggregate metric values. This is important for aggregate functions like <code>COUNT</code> and <code>AVG</code> where re-aggregation would produce incorrect results.</p><blockquote><p><strong>Note</strong>: If your data source returns raw daily rows and relies on the framework to aggregate them into weeks, months, etc., do <strong>not</strong> set this flag. The framework will handle the aggregation automatically.</p></blockquote><p>This configuration is sufficient to display the data source data in a table widget:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/table-all-data.png" alt="image"></p><h3 id="formatting-metrics-data"><a href="#formatting-metrics-data" class="header-anchor">#</a> Formatting Metrics Data</h3><p>By default, the dashboard formats metrics data as numbers. If the default formatting is not suitable, you can configure metrics to display data in other formats. In our ecommerce example, it makes sense to display the total amount as currency.</p>`,60)),s[2]||(s[2]=n("p",null,[a("The final parameter of the "),n("code",null,"ReportMetric"),a(" class constructor takes an array of options that are compatible with the "),n("code",null,"options"),a(" argument of "),n("a",{href:"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/NumberFormat/NumberFormat",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Intl.NumberFormat"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(", a browser API. The example below demonstrates a configuration ideal for displaying currency in the US format:")],-1)),s[3]||(s[3]=o(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerMetric</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportMetric</span><span class="token punctuation">(</span>
    <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">METRIC_TOTAL_AMOUNT</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme_shop_sales.total&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;Total amount&#39;</span><span class="token punctuation">,</span>
    <span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_SUM</span><span class="token punctuation">,</span>
    <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;style&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;currency&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;currency&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;USD&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The updated metric data is displayed on the dashboard as follows:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/currency.png" alt="image"></p><h3 id="custom-display-formatting"><a href="#custom-display-formatting" class="header-anchor">#</a> Custom Display Formatting</h3><p>While <code>Intl.NumberFormat</code> handles most numeric formatting needs (currencies, percentages, compact notation), some metrics require custom string transformations that cannot be achieved with standard number formatting. For example, displaying durations as &quot;2:30h&quot; instead of &quot;150&quot; minutes.</p><p>The <code>setDisplayFormatter</code> method allows you to define a server-side callback that formats metric values into human-readable strings. This formatted value is used in non-graph displays such as tables and indicators, while charts continue to use the raw numeric values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerMetric</span><span class="token punctuation">(</span>
    <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportMetric</span><span class="token punctuation">(</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">METRIC_DURATION</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;acme_entries.duration_minutes&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;Duration&#39;</span><span class="token punctuation">,</span>
        <span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_SUM</span>
    <span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">setDisplayFormatter</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$totalMinutes</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword type-casting">int</span><span class="token punctuation">)</span> <span class="token variable">$value</span><span class="token punctuation">;</span>
        <span class="token variable">$hours</span> <span class="token operator">=</span> <span class="token function">intdiv</span><span class="token punctuation">(</span><span class="token variable">$totalMinutes</span><span class="token punctuation">,</span> <span class="token number">60</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$minutes</span> <span class="token operator">=</span> <span class="token variable">$totalMinutes</span> <span class="token operator">%</span> <span class="token number">60</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token function">sprintf</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;%d:%02dh&#39;</span><span class="token punctuation">,</span> <span class="token variable">$hours</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When a display formatter is set:</p><ul><li><strong>Tables</strong>: Cell values and totals display the formatted string (e.g., &quot;2:30h&quot;)</li><li><strong>Indicators</strong>: The main value displays the formatted string</li><li><strong>Charts</strong>: Raw numeric values are used (formatting would break graph rendering)</li></ul><p>You can combine <code>setDisplayFormatter</code> with <code>intlFormatOptions</code>. If both are set, the display formatter takes precedence for non-graph displays, while <code>intlFormatOptions</code> serves as a fallback for contexts where server-side formatting isn&#39;t available.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerMetric</span><span class="token punctuation">(</span>
    <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportMetric</span><span class="token punctuation">(</span>
        <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">METRIC_DURATION</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;acme_entries.duration_minutes&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;Duration&#39;</span><span class="token punctuation">,</span>
        <span class="token class-name static-context">ReportMetric</span><span class="token operator">::</span><span class="token constant">AGGREGATE_SUM</span><span class="token punctuation">,</span>
        <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;style&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;unit&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;unit&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;minute&#39;</span><span class="token punctuation">]</span> <span class="token comment">// Fallback for charts</span>
    <span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">setDisplayFormatter</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Used for tables and indicators</span>
        <span class="token variable">$hours</span> <span class="token operator">=</span> <span class="token function">intdiv</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token keyword type-casting">int</span><span class="token punctuation">)</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token number">60</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$minutes</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword type-casting">int</span><span class="token punctuation">)</span> <span class="token variable">$value</span> <span class="token operator">%</span> <span class="token number">60</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token function">sprintf</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;%d:%02dh&#39;</span><span class="token punctuation">,</span> <span class="token variable">$hours</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="displaying-extra-dimension-data"><a href="#displaying-extra-dimension-data" class="header-anchor">#</a> Displaying Extra Dimension Data</h3><p>In our demo database structure, the products table has a <code>brand</code> column. Additionally, it references the categories table, ensuring each product is linked to a category. We can display the brand and category names in reports along with the product name by using the dimension fields feature.</p><p>Dimension fields should be added to a dimension within the data source constructor. The dimension object includes the <code>addDimensionField</code> method, accepting a configured dimension field object. Here&#39;s how we can add dimension fields for the brand and category names to the product dimension:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerDimension</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportDimension</span><span class="token punctuation">(</span>
    <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token constant">DIMENSION_PRODUCT</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme_shop_products.id&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;Product&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;product_name&#39;</span>
<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">addDimensionField</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportDimensionField</span><span class="token punctuation">(</span>
    <span class="token string single-quoted-string">&#39;oc_field_brand&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;Brand&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;brand&#39;</span><span class="token punctuation">,</span>
    <span class="token constant boolean">true</span><span class="token punctuation">,</span>
    <span class="token constant boolean">true</span>
<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">addDimensionField</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ReportDimensionField</span><span class="token punctuation">(</span>
    <span class="token string single-quoted-string">&#39;oc_field_category&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;Category&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme_shop_categories.category_name&#39;</span><span class="token punctuation">,</span>
    <span class="token constant boolean">true</span><span class="token punctuation">,</span>
    <span class="token constant boolean">true</span>
<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>ReportDimensionField</code> constructor takes these arguments:</p><div class="table"><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>$code</strong></td><td><code>string</code></td><td>specifies the field referral code. The code must begin with the <code>oc_field_</code> prefix.</td></tr><tr><td><strong>$displayName</strong></td><td><code>string</code></td><td>specifies the field name to use in reports. For example, in the Table widget, this could become the title of the dimension column. It is also used in the widget configuration popup, in the dimension dropdown. The value for this argument can be a static string, or a reference to a localization string.</td></tr><tr><td><strong>$columnName</strong></td><td><code>?string</code></td><td>optional database column name for filtering or sorting. Provide the column name to enable sorting and filtering. In most cases, you should specify a value for this argument.</td></tr><tr><td><strong>$sortable</strong></td><td><code>bool</code></td><td>specifies if the field is sortable.</td></tr><tr><td><strong>$filterable</strong></td><td><code>bool</code></td><td>specifies if the field is filterable.</td></tr></tbody></table></div><p>After registration, the dimension field will appear in the dashboard widget configurators:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/dimension-fields.png" alt="image"></p><p>The remaining task involves returning data for the dimension fields. Since <code>ReportQueryBuilder</code> does not automate this process, it&#39;s necessary to configure its underlying query to add a join and add the corresponding columns to the query. This can be accomplished in the <code>onConfigureQuery</code> callback:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ReportQueryBuilder</span><span class="token operator">::</span><span class="token function">fromFetchData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme_shop_products&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">dateColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales.sale_date&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">onConfigureMetrics</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$dimension</span><span class="token punctuation">,</span> <span class="token variable">$metrics</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$join</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$join</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_sales.product_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme_shop_products.id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">onConfigureQuery</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$dimension</span><span class="token punctuation">,</span> <span class="token variable">$metrics</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$join</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$join</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_shop_categories.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme_shop_products.category_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">addSelect</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
            <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;max(acme_shop_products.brand) as oc_field_brand&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;max(acme_shop_categories.category_name) as oc_field_category&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metricsConfiguration</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>It may seem odd that we use the <code>max</code> function for the product brand and category. The reason this is necessary is because the query is grouped by the product ID column (dimension), and we must use aggregation functions on all columns to avoid MySQL errors. This simple trick resolves the issue.</p><p>The dimension fields are now available for preview in the dashboard. Users can configure widgets to sort data by the brand or category column:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/dimension-fields-table.png" alt="image"></p><h3 id="using-the-data-source"><a href="#using-the-data-source" class="header-anchor">#</a> Using the Data Source</h3><p>A properly configured data source is immediately ready for use in all types of dashboard widgets without additional setup. For example, you can configure the Chart widget to display the top products.</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/chart-widget.png" alt="image"></p><p>In this example, the chart widget is set up as follows:</p><ul><li>Chart type: Bar</li><li>Direction: Horizontal</li><li>Data source: Our test data source</li><li>Dimension: Product</li><li>Metrics: Total amount</li><li>Limit: 5</li><li>Sort by: Total amount</li><li>Sort order: Descending</li><li>Display: Dashboard interval</li></ul><p>You can also configure the Indicator widget to display totals, with the option to filter the data by a specific brand or category:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/indicator-widgets.png" alt="image"></p><p>In this example, the Smartphones Indicator widget is set up as follows:</p><ul><li>Data source: Our test data source</li><li>Dimension: Product</li><li>Value: Total amount</li><li>Filters attribute: Category</li><li>Filter operation: Equals</li><li>Value: Smartphones</li></ul><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/indicator-smartphones.png" alt="image"></p><p>The iPhones Indicator widget uses the following filter configuration:</p><ul><li>Attribute: Product</li><li>Operation: Includes</li><li>Value: iPhone</li></ul><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/indicator-iphones.webp" alt="image"></p><h3 id="legacy-reportdataquerybuilder"><a href="#legacy-reportdataquerybuilder" class="header-anchor">#</a> Legacy ReportDataQueryBuilder</h3><p>For backward compatibility, the original <code>ReportDataQueryBuilder</code> class is still available. This class uses a constructor-based approach with 15 parameters:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportDataQueryBuilder</span><span class="token punctuation">;</span>

<span class="token variable">$reportQueryBuilder</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ReportDataQueryBuilder</span><span class="token punctuation">(</span>
    <span class="token string single-quoted-string">&#39;acme_shop_products&#39;</span><span class="token punctuation">,</span>      <span class="token comment">// Table name</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dimension</span><span class="token punctuation">,</span>          <span class="token comment">// Dimension</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metrics</span><span class="token punctuation">,</span>            <span class="token comment">// Metrics array</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">orderRule</span><span class="token punctuation">,</span>          <span class="token comment">// Order rule</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dimensionFilters</span><span class="token punctuation">,</span>   <span class="token comment">// Filters</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">limit</span><span class="token punctuation">,</span>              <span class="token comment">// Limit</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">paginationParams</span><span class="token punctuation">,</span>   <span class="token comment">// Pagination</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">groupInterval</span><span class="token punctuation">,</span>      <span class="token comment">// Group interval</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">hideEmptyDimensionValues</span><span class="token punctuation">,</span>  <span class="token comment">// Hide empty values</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dateStart</span><span class="token punctuation">,</span>          <span class="token comment">// Date start</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">dateEnd</span><span class="token punctuation">,</span>            <span class="token comment">// Date end</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">startTimestamp</span><span class="token punctuation">,</span>     <span class="token comment">// Start timestamp</span>
    <span class="token string single-quoted-string">&#39;sale_date&#39;</span><span class="token punctuation">,</span>               <span class="token comment">// Date column</span>
    <span class="token constant">null</span><span class="token punctuation">,</span>                      <span class="token comment">// Timestamp column</span>
    <span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">totalsOnly</span>          <span class="token comment">// Totals only</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$reportQueryBuilder</span><span class="token operator">-&gt;</span><span class="token function">onConfigureMetrics</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$dimension</span><span class="token punctuation">,</span> <span class="token variable">$metrics</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Configure metrics...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token variable">$reportQueryBuilder</span><span class="token operator">-&gt;</span><span class="token function">getFetchDataResult</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token operator">-&gt;</span><span class="token property">metricsConfiguration</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The legacy class also provides a <code>fromFetchData</code> static method as a shorthand:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$reportQueryBuilder</span> <span class="token operator">=</span> <span class="token class-name static-context">ReportDataQueryBuilder</span><span class="token operator">::</span><span class="token function">fromFetchData</span><span class="token punctuation">(</span>
    <span class="token variable">$data</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme_shop_products&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;sale_date&#39;</span><span class="token punctuation">,</span>  <span class="token comment">// Date column</span>
    <span class="token constant">null</span>          <span class="token comment">// Timestamp column</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: New implementations should use <code>ReportQueryBuilder</code> for its cleaner fluent interface and better readability.</p></blockquote>`,43))])}const v=r(u,[["render",d]]);export{y as __pageData,v as default};
